if(page==='hat'){detail('Crazy Hat Day','Tuesday, September 29 · your child',`<div class="source"><div class="label">From the school email</div><p>“Tuesday is Crazy Hat Day. Please send your student in a fun hat.”</p></div><div class="notice">Order by Friday, September 25 at 3:00 PM for the sample Sunday delivery. The event is Tuesday, but the order needs action today.</div><div class="option recommended"><div class="tag">SUGGESTED</div><h3>Choose a hat online</h3><p>See a sample option with an estimated Sunday arrival. You approve before the demo marks it handled.</p><button onclick="go('hat-order')">View option →</button></div><div class="option"><h3>Reminder for the order deadline</h3><p>${state.hatReminder?'Demo reminder set for Friday at 1:00 PM.':'Set a sample reminder before the 3:00 PM order deadline.'}</p><button onclick="state.hatReminder=true;save();render()">${state.hatReminder?'Reminder set ✓':'Set demo reminder'}</button></div><div class="option"><h3>We already have one</h3><p>Set a Monday evening reminder to put it by your child’s backpack.</p><button onclick="set('hat','handled','hat-done')">Use ours →</button></div><div class="option"><h3>Pick one up Monday</h3><p>Suggested errand window: after pickup, around 4:10–4:40. Route and store availability are sample data.</p><button onclick="go('hat-errand')">Plan errand →</button></div>`);return}
