let trial={events:structuredClone(trialDefaults),checks:{},meal:'',grocery:{}};
let sharedReady=false,sharedBase=null,sharedPending=false,sharedFailed=false,sharedStatus='Loading shared plan…',sharedRevision=0;
let taskView=localStorage.getItem('daylight-task-view')||'Alicia';
let trialEdit=null,trialDate='2026-10-12',trialReturn='plan-weekend',trialToast='';
function trialSave(){sharedStatus='Saving shared changes…';sharedFailed=false;queueSharedSave();return true}
function planDiff(base,current){let out=[];for(const e of current.events){let old=base.events.find(x=>x.id===e.id);if(!old)out.push({type:'add',event:e});else for(const key of Object.keys(e))if(key!=='id'&&JSON.stringify(e[key])!==JSON.stringify(old[key]))out.push({type:'event',id:e.id,key,value:e[key]})}for(const key of ['checks','grocery'])for(const k of Object.keys(current[key]||{}))if(current[key][k]!==base[key]?.[k])out.push({type:key,key:k,value:current[key][k]});if(current.meal!==base.meal)out.push({type:'meal',value:current.meal});return out}
async function queueSharedSave(){if(!sharedReady||sharedPending)return;sharedPending=true;try{while(true){let submitted=structuredClone(trial),ops=planDiff(sharedBase,submitted);if(!ops.length)break;const res=await fetch('/api/plan',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({ops})});if(!res.ok)throw new Error('save');let body=await res.json();sharedRevision=body.revision;let newer=planDiff(submitted,trial);sharedBase=structuredClone(body.plan);trial=applyClientOps(structuredClone(body.plan),newer)}sharedStatus='Shared plan saved';sharedFailed=false}catch(e){sharedStatus='Changes not saved yet. Keep this page open and tap Retry.';sharedFailed=true}finally{sharedPending=false;if(page!=='trial-edit'&&!['TEXTAREA','INPUT'].includes(document.activeElement?.tagName))render()}}
function applyClientOps(plan,ops){for(const op of ops){if(op.type==='add'){if(!plan.events.some(e=>e.id===op.event.id))plan.events.push(op.event)}else if(op.type==='event'){let e=plan.events.find(e=>e.id===op.id);if(e)e[op.key]=op.value}else if(op.type==='meal')plan.meal=op.value;else plan[op.type][op.key]=op.value}return plan}
async function loadShared(initial=false){if(sharedPending||sharedFailed)return;try{let res=await fetch('/api/plan',{cache:'no-store'});if(!res.ok)throw new Error('load');let data=await res.json();if(sharedPending||sharedFailed||data.revision<sharedRevision)return;sharedRevision=data.revision;trial=data.plan;sharedBase=structuredClone(trial);sharedReady=true;sharedStatus='Shared plan up to date';if(page!=='trial-edit'&&!['TEXTAREA','INPUT'].includes(document.activeElement?.tagName))render()}catch(e){sharedStatus='Shared plan unavailable. Retry before making changes.';sharedReady=false;render()}}

function trialSet(id,key,value){let e=trial.events.find(e=>e.id===id);if(e){e[key]=value;trialSave();render()}}
function trialDateLabel(date){return new Date(date+'T12:00:00').toLocaleDateString('en-US',{weekday:'long',month:'short',day:'numeric'})}
function trialTime(e){if(!e.start)return 'Time needed';const fmt=t=>new Date('2026-10-09T'+t).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'});return fmt(e.start)+(e.end?'–'+fmt(e.end):'')}
function trialHeader(title,range,text){return `<header class="top weekend-head"><div class="brandline"><div class="brand">daylight<i>✳</i></div><div class="demo">Family trial</div></div><div class="date">${range} · 2026 · Pacific time</div><h1>${title}</h1><p>${text}</p></header>`}
function trialNotice(){return `<div class="source" role="status"><strong>${esc(sharedStatus)}</strong>${sharedFailed?'<button class="plain" onclick="queueSharedSave()">Retry saving</button>':''}</div><p class="small">One shared family plan. Updates refresh about every 10 seconds while the app is open. No texts, bookings, purchases, calendar updates or push notifications are sent.</p>`}
function trialPersonSelect(value){return ['Unassigned','Alicia','Taylor','Together','Carpool / other'].map(v=>`<option ${value===v?'selected':''}>${v}</option>`).join('')}
function rideFields(e,inForm=false){return `<fieldset style="border:0;padding:0;margin:16px 0"><legend style="font-weight:700;margin-bottom:10px">Who’s driving?</legend><div class="assigngrid">${['dropoff','pickup'].map(key=>`<label>${key==='dropoff'?'Drop-off':'Pickup'}<select ${inForm?`name="${key}"`:`onchange="trialSet('${e.id}','${key}',this.value)"`} aria-label="${key==='dropoff'?'Drop-off':'Pickup'} driver for ${esc(e.title)}">${trialPersonSelect(e[key])}</select></label>`).join('')}</div></fieldset>`}
function trialEventCard(e){if(e.kind==='spirit')return executionCard(e);return `<article class="card planner-card ${e.status==='Done'?'done':''}"><div class="eyebrow">${esc(e.who||'Family')} · ${esc(e.status)}</div><h3>${esc(e.title)}</h3><div class="eventmeta"><strong>${esc(trialTime(e))}</strong><br>${esc(e.place||'Location needed')}</div>${e.note?`<p class="planner-note">${esc(e.note)}</p>`:''}${e.ride?rideFields(e):`<label class="field">Responsible<select class="textbox" aria-label="Responsible for ${esc(e.title)}" onchange="trialSet('${e.id}','owner',this.value)">${trialPersonSelect(e.owner)}</select></label>`}<div class="card-actions"><button class="open" onclick="editTrial('${e.id}')">Edit details</button>${e.kind==='dinner'?'<button class="secondary" onclick="openDinner(\''+e.id+'\')">Handle dinner</button>':`<button class="secondary" onclick="trialSet('${e.id}','status','${e.status==='Done'?'Confirmed':'Done'}')">${e.status==='Done'?'Reopen':'Mark done'}</button>`}</div>${e.kind?`<button class="plain" onclick="${e.kind==='dinner'?`openDinner('${e.id}')`:`go('trial-${e.kind}')`}">${({outing:'Find outing ideas',dinner:'Choose dinner',playdate:'Draft playdate request'})[e.kind]}</button>`:''}</article>`}
function trialAlerts(events){let notes=[];let missing=events.filter(e=>!e.start&&e.status!=='Done'&&e.kind!=='spirit');if(missing.length)notes.push(`${missing.length} items need times before the plan can be checked fully.`);let rides=events.filter(e=>e.ride&&e.status!=='Done'&&(!e.dropoff||e.dropoff==='Unassigned'||!e.pickup||e.pickup==='Unassigned'));if(rides.length)notes.push(`${rides.length} practices still need a driver for one or both rides.`);const active=events.filter(e=>e.start&&e.end&&e.status!=='Done');let persons=e=>[...new Set((e.who||'').split(',').map(x=>x.trim()).concat([e.ride?'':e.owner,e.dropoff,e.pickup]).filter(x=>x&&x!=='Unassigned'&&x!=='Together'&&x!=='Carpool / other'&&x!=='Family'))];for(let i=0;i<active.length;i++)for(let j=i+1;j<active.length;j++){let a=active[i],b=active[j];if(a.date===b.date&&a.start<b.end&&b.start<a.end&&persons(a).some(x=>persons(b).includes(x)))notes.push(`Check overlap: ${a.title} and ${b.title}.`)}return notes}
function editTrial(id){trialEdit=id;trialReturn=page.startsWith('plan-')?page:'plan-weekend';go('trial-edit')}
function addTrial(date){trialEdit=null;trialDate=date;trialReturn=page;go('trial-edit')}
function saveTrialForm(ev){ev.preventDefault();const f=new FormData(ev.target);let start=f.get('start'),end=f.get('end');if(start&&end&&end<=start){document.getElementById('formerror').textContent='End time must be after start time. For an overnight plan, put pickup details in Notes.';return}let entry={id:trialEdit||'event-'+crypto.randomUUID(),date:f.get('date'),title:f.get('title').trim(),who:f.get('who').trim(),start,end,place:f.get('place').trim(),owner:f.get('owner')||trial.events.find(e=>e.id===trialEdit)?.owner||'Unassigned',status:f.get('status'),note:f.get('note').trim()};if(f.has('dropoff'))entry.dropoff=f.get('dropoff');if(f.has('pickup'))entry.pickup=f.get('pickup');if(!entry.title)return;if(trialEdit){let i=trial.events.findIndex(e=>e.id===trialEdit);trial.events[i]={...trial.events[i],...entry}}else trial.events.push(entry);trialSave();trialToast='Saving your shared plan…';go(entry.date<'2026-10-12'?'plan-weekend':'plan-week')}
function trialCopy(id){let el=document.getElementById(id);navigator.clipboard?.writeText(el.value).then(()=>{document.getElementById('copy-result').textContent='Copied. Paste into your messages when ready; nothing was sent.'}).catch(()=>{el.select();document.getElementById('copy-result').textContent='Select and copy the text manually.'})}
